#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

/*
Ideia:
- Valor final = soma dos a_i usados menos a soma dos b_i de todas as sílabas usadas
  exceto a última (e exceto as que foram zeradas).
- Cada sílaba i (i != última) contribui: 0 (fora), a_i - b_i (usada sem zerar),
  a_i (usada com zerada). Com no máximo K zeradas.
- Base (sem zerar): incluir todas com a_i > b_i, valendo (a_i - b_i).
  Zerar a sílaba i adiciona ganho g_i = b_i (se a_i > b_i) ou a_i (se a_i <= b_i).
  Resposta para última sílaba L: a_L + base(sem L) + top-K ganhos entre i != L.
- Esse valor é alcançável: com todas as sílabas não-últimas tendo contribuição
  positiva (a_i > c_i, c_i = b_i ou 0), a nasalidade acumulada P satisfaz
  P >= a_{atual} em todo ponto, logo qualquer ordem satisfaz a_i + A >= B.
*/

int main(){
    int n; long long k;
    if(scanf("%d %lld", &n, &k) != 2) return 0;
    vector<ll> a(n), b(n);
    for(int i = 0; i < n; i++) scanf("%lld", &a[i]);
    for(int i = 0; i < n; i++) scanf("%lld", &b[i]);

    ll base = 0;
    vector<ll> gain(n);
    for(int i = 0; i < n; i++){
        if(a[i] > b[i]){ base += a[i] - b[i]; gain[i] = b[i]; }
        else gain[i] = a[i];
    }

    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int x, int y){
        if(gain[x] != gain[y]) return gain[x] > gain[y];
        return x < y;
    });
    vector<int> pos(n);
    vector<ll> pre(n + 1, 0);
    for(int r = 0; r < n; r++){
        pos[ord[r]] = r + 1;
        pre[r + 1] = pre[r] + gain[ord[r]];
    }

    ll kk = min(k, (ll)n);
    ll ans = 0;
    for(int i = 0; i < n; i++){
        ll v = a[i] + base;
        if(a[i] > b[i]) v -= a[i] - b[i]; // se i e ultima, nao entra na base com (a-b)
        int p = pos[i];
        ll t;
        if((ll)p > kk) t = pre[kk];
        else t = pre[min(kk + 1, (ll)n)] - gain[i];
        v += t;
        ans = max(ans, v);
    }
    printf("%lld\n", ans);
    return 0;
}
